//! Questions and answers for a game page. The same list renders on the page and as `FAQPage`
//! JSON-LD, so the visible text and the structured data never drift apart.
//!
//! A FAQ generated by `describe-games` and stored on the game wins. Without one, the template
//! answers below are written from the page's own data.

use recomphub_shared::{
    AuthorDto, FaqItem, GameDetail, MaintenanceLevel, PortCard, TargetPlatform,
};

use crate::components::ui::{target_label, version_label};

/// Desktop targets a player asks about together.
const DESKTOP: [&str; 3] = ["windows", "macos", "linux"];

/// The FAQ for a game page: the stored one when present, otherwise the template answers.
pub fn game_faq(detail: &GameDetail) -> Vec<FaqItem> {
    if detail.faq.is_empty() {
        template_faq(detail)
    } else {
        let mut out = detail.faq.clone();
        if !detail.ports.is_empty() {
            let ports = ranked(&detail.ports);
            let comparison = comparison_faq(&ports);
            if !out.iter().any(|f| f.question == comparison.question) {
                out.push(comparison);
            }
        }
        out
    }
}

fn comparison_faq(ports: &[&PortCard]) -> FaqItem {
    let entries = ports.iter().map(|p| {
        let targets = if p.targets.is_empty() {
            "no recorded target platforms".to_string()
        } else {
            format!("targets {}", join_and(&labels(&p.targets)))
        };
        format!(
            "{} is recorded as {} and has {targets}",
            p.name,
            playability_label(&p.playability)
        )
    });
    FaqItem {
        question: "How do the listed projects compare?".into(),
        answer: format!(
            "Catalog records list {}. Playability labels are community-reported and are not independent test results.",
            join_and(&entries.collect::<Vec<_>>())
        ),
    }
}

fn playability_label(status: &str) -> &'static str {
    match status {
        "complete" => "complete",
        "playable" => "playable",
        "in_progress" => "in progress",
        _ => "not rated",
    }
}

fn template_faq(detail: &GameDetail) -> Vec<FaqItem> {
    let game = detail.game.name.as_str();
    let ports = ranked(&detail.ports);
    let mut out = vec![desktop_faq(detail, &ports)];
    if let Some(first) = ports.first() {
        out.push(comparison_faq(&ports));
        out.extend(still_worked_on_faq(first));
        out.extend(who_faq(first));
    }
    if !ports.is_empty() || !detail.decompilations.is_empty() {
        out.push(own_copy_faq());
    }
    out.extend(platform_faq(game, &ports, "web"));
    out.extend(platform_faq(game, &ports, "android"));
    if !detail.decompilations.is_empty() {
        out.push(decomp_faq(game, &detail.decompilations));
    }
    if ports.is_empty() {
        out.push(unported_faq(game, detail.game.want_count));
    }
    out
}

/// "Can I play X on PC, Mac or Linux?" The original release counts when it runs there natively.
fn desktop_faq(detail: &GameDetail, ports: &[&PortCard]) -> FaqItem {
    let native: Vec<&str> = DESKTOP
        .into_iter()
        .filter(|t| original_runs_on(detail, t))
        .collect();
    let mut by_port: Vec<(usize, Vec<&str>)> = Vec::new();
    let mut missing: Vec<&str> = Vec::new();
    for target in DESKTOP {
        if native.contains(&target) {
            continue;
        }
        match ports
            .iter()
            .position(|p| p.targets.iter().any(|t| t.as_str() == target))
        {
            Some(i) => match by_port.iter_mut().find(|(j, _)| *j == i) {
                Some((_, list)) => list.push(target),
                None => by_port.push((i, vec![target])),
            },
            None => missing.push(target),
        }
    }

    let mut sentences = Vec::new();
    if !native.is_empty() {
        sentences.push(format!(
            "The original release already runs natively on {}.",
            join_and(&labels(&native))
        ));
    }
    let coverage: Vec<String> = by_port
        .iter()
        .map(|(i, targets)| format!("{} covers {}", ports[*i].name, join_and(&labels(targets))))
        .collect();
    if let [(i, _)] = by_port.as_slice() {
        sentences.push(format!("{}.", coverage[0]));
        sentences.push(status_sentence(ports[*i]));
    } else if !coverage.is_empty() {
        sentences.push(format!("{}.", join_and(&coverage)));
    }
    if !missing.is_empty() {
        let names = join_and(&labels(&missing));
        sentences.push(if ports.is_empty() {
            format!("There is no known port for {names} yet.")
        } else {
            format!("Nothing covers {names} yet.")
        });
    }

    FaqItem {
        question: format!("Can I play {} on PC, Mac or Linux?", detail.game.name),
        answer: sentences.join(" "),
    }
}

/// "Is X still being worked on?" From the maintenance level, last change and latest release.
fn still_worked_on_faq(best: &PortCard) -> Option<FaqItem> {
    let mut sentences = Vec::new();
    if let Some(m) = best.maintenance {
        sentences.push(level_sentence(m.level).to_string());
        if let Some(at) = m.last_commit_at {
            sentences.push(format!("The last commit landed in {}.", at.format("%B %Y")));
        }
    }
    if let (Some(version), Some(at)) = (best.latest_version.as_deref(), best.latest_release_at) {
        sentences.push(format!(
            "The latest release, {}, came out in {}.",
            version_label(version),
            at.format("%B %Y")
        ));
    }
    if sentences.is_empty() {
        return None;
    }
    Some(FaqItem {
        question: format!("Is {} still being worked on?", best.name),
        answer: sentences.join(" "),
    })
}

fn level_sentence(level: MaintenanceLevel) -> &'static str {
    match level {
        MaintenanceLevel::Active => "It's in active development.",
        MaintenanceLevel::Maintained => "It's still maintained.",
        MaintenanceLevel::Slowing => "It's slowed down.",
        MaintenanceLevel::Dormant => "It's been quiet for a long time.",
        MaintenanceLevel::Archived => "The repository is archived, so no new changes are expected.",
    }
}

/// "Who's behind X?" from the port's named authors. Accounts that just repeat the project's name
/// are left out, since they say nothing about who made it.
fn who_faq(best: &PortCard) -> Option<FaqItem> {
    let names: Vec<String> = best
        .authors
        .iter()
        .filter(|a| !is_project_account(a, &best.name))
        .filter_map(author_name)
        .collect();
    if names.is_empty() {
        return None;
    }
    let shown = if names.len() > 4 {
        format!("{} and {} more", names[..4].join(", "), names.len() - 4)
    } else {
        join_and(&names)
    };
    Some(FaqItem {
        question: format!("Who's behind {}?", best.name),
        answer: format!("{} is made by {shown}.", best.name),
    })
}

/// True when the author is the project's own account, matched by login or display name.
fn is_project_account(author: &AuthorDto, project: &str) -> bool {
    author
        .github_login
        .as_deref()
        .is_some_and(|login| login.eq_ignore_ascii_case(project))
        || author.name.trim().eq_ignore_ascii_case(project)
}

fn author_name(author: &AuthorDto) -> Option<String> {
    let name = author.name.trim();
    if name.is_empty() {
        author.github_login.clone()
    } else {
        Some(name.to_string())
    }
}

/// Asset requirements vary by project; the catalog does not supply game assets.
fn own_copy_faq() -> FaqItem {
    FaqItem {
        question: "Do I need the original game?".to_string(),
        answer: "Requirements vary by project. Check the project's README or release instructions; if original game assets are required, use only a copy you are entitled to use. RecompHub does not provide game assets.".to_string(),
    }
}

/// "Can I play X in a web browser?" and "Can I play X on Android?", only when a port covers it.
fn platform_faq(game: &str, ports: &[&PortCard], target: &str) -> Option<FaqItem> {
    let (place, runs) = match target {
        "web" => ("in a web browser", "the web"),
        "android" => ("on Android", "Android"),
        _ => return None,
    };
    let port = ports
        .iter()
        .find(|p| p.targets.iter().any(|t| t.as_str() == target))?;
    Some(FaqItem {
        question: format!("Can I play {game} {place}?"),
        answer: format!("{} covers {runs}. {}", port.name, status_sentence(port)),
    })
}

/// "Is there a decompilation of X?" Decompilations are the groundwork, not something to play.
fn decomp_faq(game: &str, decomps: &[PortCard]) -> FaqItem {
    let names: Vec<String> = decomps.iter().map(|p| p.name.clone()).collect();
    let (verb, pronoun) = if names.len() == 1 {
        ("is a decompilation", "It")
    } else {
        ("are decompilations", "They")
    };
    FaqItem {
        question: format!("Is there a decompilation of {game}?"),
        answer: format!(
            "{} {verb} of {game}. {pronoun} turns the original machine code back into readable source, the groundwork most native ports are built on, but not something you play on its own.",
            join_and(&names)
        ),
    }
}

/// For games with no port: nobody has published one, the demand, and where to look next.
fn unported_faq(game: &str, want_count: i32) -> FaqItem {
    let demand = match want_count {
        0 => String::new(),
        1 => " One person has asked for a port.".to_string(),
        n => format!(" {n} people have asked for a port."),
    };
    FaqItem {
        question: format!("Is anyone working on a port of {game}?"),
        answer: format!(
            "Nobody has published one on RecompHub yet.{demand} Games people want that still have no port are listed under What to work on next."
        ),
    }
}

/// Ports ordered best first: playability, then GitHub stars, then name.
fn ranked(ports: &[PortCard]) -> Vec<&PortCard> {
    let mut out: Vec<&PortCard> = ports.iter().collect();
    out.sort_by(|a, b| {
        playability_rank(&b.playability)
            .cmp(&playability_rank(&a.playability))
            .then(b.github_stars.cmp(&a.github_stars))
            .then(a.name.cmp(&b.name))
    });
    out
}

fn playability_rank(p: &str) -> u8 {
    match p {
        "complete" => 3,
        "playable" => 2,
        "in_progress" => 1,
        _ => 0,
    }
}

/// One sentence on how far a port has got and which release it is on, e.g. "It's playable, and
/// the latest release is v1.2."
fn status_sentence(p: &PortCard) -> String {
    let play = match p.playability.as_str() {
        "complete" => "It's fully playable",
        "playable" => "It's playable",
        "in_progress" => "It's still in progress",
        _ => "Nobody has rated how playable it is yet",
    };
    match p.latest_version.as_deref() {
        Some(v) if is_release_number(v) => {
            format!("{play}, and the latest release is {}.", version_label(v))
        }
        _ => format!("{play}."),
    }
}

/// A version such as "v1.2" or "0.3", as opposed to a tag such as "latest".
fn is_release_number(v: &str) -> bool {
    v.trim_start_matches(['v', 'V'])
        .starts_with(|c: char| c.is_ascii_digit())
}

fn original_runs_on(detail: &GameDetail, target: &str) -> bool {
    detail.platforms.iter().any(|p| {
        p.slug
            .as_deref()
            .and_then(TargetPlatform::from_platform_slug)
            .is_some_and(|t| t.as_str() == target)
    })
}

/// Player-facing labels for target slugs.
fn labels<S: AsRef<str>>(slugs: &[S]) -> Vec<String> {
    slugs.iter().map(|s| target_label(s.as_ref())).collect()
}

/// "a", "a and b", "a, b and c".
fn join_and(items: &[String]) -> String {
    match items {
        [] => String::new(),
        [one] => one.clone(),
        [init @ .., last] => format!("{} and {last}", init.join(", ")),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use recomphub_shared::{GameCard, MaintenanceDto, PlatformRef};

    fn port(name: &str, targets: &[&str], playability: &str, stars: i32) -> PortCard {
        PortCard {
            id: 1,
            slug: name.to_lowercase(),
            game_id: 1,
            game_slug: "nfsmw".into(),
            game_name: "Need for Speed: Most Wanted".into(),
            name: name.into(),
            kind: "recomp".into(),
            kind_label: "Static recompilation".into(),
            targets: targets.iter().map(|t| t.to_string()).collect(),
            authors: vec![],
            ai_usage: "none".into(),
            ai_tools: vec![],
            ai_evidence: vec![],
            playability: playability.into(),
            latest_version: Some("0.3".into()),
            latest_release_url: None,
            latest_release_at: None,
            release_state: "released".into(),
            release_state_label: "Released".into(),
            github_stars: stars,
            star_count: 0,
            repo_url: String::new(),
            cover: None,
            maintenance: None,
        }
    }

    fn detail(ports: Vec<PortCard>, want_count: i32) -> GameDetail {
        GameDetail {
            game: GameCard {
                id: 1,
                slug: "nfsmw".into(),
                name: "Need for Speed: Most Wanted".into(),
                release_year: Some(2005),
                cover: None,
                port_count: ports.len() as i32,
                want_count,
                targets: vec![],
                best_playability: None,
                popularity: 0,
            },
            summary: None,
            alt_names: vec![],
            developer: None,
            publisher: None,
            genres: vec![],
            first_release_date: None,
            platforms: vec![PlatformRef {
                id: 1,
                slug: Some("ps2".into()),
                name: "PlayStation 2".into(),
                abbreviation: None,
                family: None,
                game_count: 0,
                ported_count: 0,
            }],
            screenshots: vec![],
            og: None,
            ports,
            decompilations: vec![],
            videos: vec![],
            related: vec![],
            total_github_stars: 0,
            live_viewers: 0,
            faq: vec![],
        }
    }

    fn answer<'a>(faq: &'a [FaqItem], question_part: &str) -> &'a str {
        &faq.iter()
            .find(|f| f.question.contains(question_part))
            .unwrap()
            .answer
    }

    #[test]
    fn stored_faq_wins_over_templates() {
        let mut d = detail(
            vec![port("NFSMW-Recompiled", &["windows"], "playable", 5)],
            0,
        );
        d.faq = vec![FaqItem {
            question: "Stored?".into(),
            answer: "Stored answer.".into(),
        }];
        let faq = game_faq(&d);
        assert_eq!(faq[0].answer, "Stored answer.");
        assert!(faq[1].answer.contains("NFSMW-Recompiled"));
        assert!(faq[1].answer.contains("playable"));
    }

    #[test]
    fn single_port_reports_coverage_and_uncovered_targets() {
        let faq = game_faq(&detail(
            vec![port("NFSMW-Recompiled", &["windows"], "playable", 5)],
            0,
        ));
        let a = answer(&faq, "on PC, Mac or Linux");
        assert!(a.contains("NFSMW-Recompiled covers Windows"));
        assert!(a.contains("macOS"));
        assert!(a.contains("Linux"));
    }

    #[test]
    fn comparison_exposes_recorded_targets_and_community_status() {
        let ports = [
            port("NFSMW-Recompiled", &["windows"], "playable", 500),
            port("speedbreaker", &["windows", "macos"], "complete", 40),
        ];
        let item = comparison_faq(&[&ports[0], &ports[1]]);
        let (_, records) = item.answer.split_once(&ports[0].name).unwrap();
        let (first, second) = records.split_once(&ports[1].name).unwrap();
        assert!(first.contains("playable"));
        assert!(first.contains("Windows"));
        assert!(!first.contains("macOS"));
        assert!(second.contains("complete"));
        assert!(second.contains("Windows"));
        assert!(second.contains("macOS"));
        assert!(item.answer.contains("community-reported"));
    }

    #[test]
    fn several_ports_report_disjoint_target_coverage() {
        let faq = game_faq(&detail(
            vec![
                port("speedbreaker", &["windows", "macos"], "complete", 40),
                port("NFSMW-Recompiled", &["linux"], "playable", 500),
            ],
            0,
        ));
        let a = answer(&faq, "on PC, Mac or Linux");
        assert!(a.contains("speedbreaker covers Windows and macOS"));
        assert!(a.contains("NFSMW-Recompiled covers Linux"));
    }

    #[test]
    fn original_native_platform_is_stated_without_a_port() {
        let mut d = detail(vec![port("NFSMW-Recompiled", &["linux"], "playable", 5)], 0);
        d.platforms = vec![PlatformRef {
            id: 2,
            slug: Some("win".into()),
            name: "PC (Microsoft Windows)".into(),
            abbreviation: None,
            family: None,
            game_count: 0,
            ported_count: 0,
        }];
        let faq = game_faq(&d);
        let a = answer(&faq, "on PC, Mac or Linux");
        assert!(a.contains("natively on Windows"), "{a}");
        assert!(a.contains("NFSMW-Recompiled covers Linux"), "{a}");
    }

    #[test]
    fn no_ports_reports_platform_gap_and_demand() {
        let faq = game_faq(&detail(vec![], 12));
        let coverage = answer(&faq, "on PC, Mac or Linux");
        assert!(coverage.contains("Windows"));
        assert!(coverage.contains("macOS"));
        assert!(coverage.contains("Linux"));
        let demand = answer(&faq, "Is anyone working on a port");
        assert!(demand.contains("12 people have asked for a port."));
        assert!(demand.contains("What to work on next"));
        assert!(!faq.iter().any(|f| f.question.starts_with("Do I need")));
    }

    #[test]
    fn maintenance_and_release_dates_answer_whether_work_continues() {
        let mut p = port("NFSMW-Recompiled", &["windows"], "playable", 5);
        p.maintenance = Some(MaintenanceDto {
            level: MaintenanceLevel::Slowing,
            score: 0,
            last_commit_at: None,
            commits_30d: 0,
            commits_90d: 0,
            commits_365d: 0,
            committers_180d: 0,
            releases_365d: 0,
        });
        let faq = game_faq(&detail(vec![p], 0));
        assert!(answer(&faq, "still being worked on").contains("slowed down"));
    }

    #[test]
    fn authors_are_named_by_login_when_they_have_no_display_name() {
        let mut p = port("NFSMW-Recompiled", &["windows"], "playable", 5);
        p.authors = vec![AuthorDto {
            github_login: Some("ada".into()),
            name: " ".into(),
            role: "owner".into(),
            avatar: None,
            commits: None,
            funding: vec![],
        }];
        let faq = game_faq(&detail(vec![p], 0));
        assert!(answer(&faq, "Who's behind").contains("ada"));
    }

    #[test]
    fn unrated_port_says_so_and_gives_its_release() {
        let faq = game_faq(&detail(
            vec![port("NFSMW Android Evolved", &["android"], "", 5)],
            0,
        ));
        let a = answer(&faq, "on Android");
        assert!(a.contains("Nobody has rated how playable it is yet"), "{a}");
        assert!(a.contains("latest release is"), "{a}");
        assert!(a.contains("0.3"), "{a}");
    }

    #[test]
    fn org_accounts_are_not_named_as_authors() {
        let mut p = port("NFSMW-Recompiled", &["windows"], "playable", 5);
        p.authors = vec![
            AuthorDto {
                github_login: Some("nfsmw-recompiled".into()),
                name: "NFSMW-Recompiled".into(),
                role: "owner".into(),
                avatar: None,
                commits: None,
                funding: vec![],
            },
            AuthorDto {
                github_login: Some("wiseguy".into()),
                name: "Mr. Wiseguy".into(),
                role: "contributor".into(),
                avatar: None,
                commits: None,
                funding: vec![],
            },
        ];
        let faq = game_faq(&detail(vec![p], 0));
        assert!(answer(&faq, "Who's behind").contains("Mr. Wiseguy"));
    }

    #[test]
    fn who_question_is_dropped_when_only_org_accounts_remain() {
        let mut p = port("NFSMW-Recompiled", &["windows"], "playable", 5);
        p.authors = vec![AuthorDto {
            github_login: Some("NFSMW-Recompiled".into()),
            name: String::new(),
            role: "owner".into(),
            avatar: None,
            commits: None,
            funding: vec![],
        }];
        let faq = game_faq(&detail(vec![p], 0));
        assert!(!faq.iter().any(|f| f.question.starts_with("Who's behind")));
    }
}
